mapper.select:
select s.suggestion_id as suggestionId, s.enterprise_id as enterpriseId, s.product_id as productId, s.calc_date as calcDate, s.suggest_qty as suggestQty, s.target_qty as targetQty, s.daily_out_qty as dailyOutQty, s.available_qty as availableQty, s.in_transit_qty as inTransitQty, s.safety_stock as safetyStock, s.max_stock as maxStock, s.season_coef as seasonCoef, s.status as status, s.order_id as orderId, s.create_time as createTime, p.product_code as productCode, p.product_name as productName, p.unit as unit from t_replenish_suggestion s inner join t_product p on p.product_id = s.product_id and p.del_flag = '0' where s.enterprise_id = #{enterpriseId}
and s.status = #{status}
and (p.product_name like concat('%', #{keyword}, '%') or p.product_code like concat('%', #{keyword}, '%'))
order by s.suggest_qty desc, s.suggestion_id desc
